<?php
require_once __DIR__ . '/bootstrap.php';
$user = require_user($conn);
$stmt = $conn->prepare('SELECT * FROM pedidos WHERE usuario_id = ? ORDER BY id DESC');
$stmt->bind_param('i', $user['id']); $stmt->execute(); $orders = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$lines = $conn->prepare('SELECT nome_produto,quantidade,preco_unitario FROM itens_pedido WHERE pedido_id = ?');
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meus pedidos | Lumora Café</title><link rel="stylesheet" href="upgrade.css"></head><body><header class="bar"><a href="index.php">☕ Lumora Café</a><nav><a href="carrinho.php">Carrinho</a><a href="logout.php">Sair</a></nav></header><main class="wrap"><h1>Meus pedidos</h1><?php if (isset($_GET['novo'])): ?><p class="success">Pedido registrado! Acompanhe o status abaixo.</p><?php endif; ?><?php if (!$orders): ?><p>Nenhum pedido ainda. <a href="index.php#cardapio">Veja o cardápio</a>.</p><?php endif; ?><?php foreach ($orders as $o): ?><article class="panel"><h2>Pedido #<?= (int)$o['id'] ?> · <?= h(str_replace('_',' ', $o['status'])) ?></h2><p><?= h($o['criado_em']) ?> · <?= h($o['tipo_entrega']) ?> · <?= money($o['total']) ?></p><p>Pagamento <?= h(str_replace('_',' ', $o['forma_pagamento'])) ?></p><?php if ($o['tipo_entrega'] === 'delivery'): ?><p>Recebedor: <?= h($o['recebedor']) ?> · Telefone: <?= h($o['telefone']) ?></p><p>Entrega: <?= h($o['rua'] ? $o['rua'] . ', ' . $o['numero'] . ($o['complemento'] ? ', ' . $o['complemento'] : '') . ' — ' . $o['bairro'] . ', ' . $o['cidade'] . '/' . $o['estado'] : $o['endereco']) ?> · CEP <?= h($o['cep']) ?></p><?php if ($o['referencia']): ?><p>Referência: <?= h($o['referencia']) ?></p><?php endif; ?><?php endif; ?><ul><?php $oid=(int)$o['id']; $lines->bind_param('i',$oid); $lines->execute(); foreach ($lines->get_result() as $line): ?><li><?= (int)$line['quantidade'] ?> × <?= h($line['nome_produto']) ?> — <?= money($line['preco_unitario']) ?> cada</li><?php endforeach; ?></ul></article><?php endforeach; ?></main></body></html>
